const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types=['신사','젊은 신사','귀부인','교수','메이드','탐정','신문 소년','선원','비행사','화가','집사','간호사','기자','마술사','노동자','사교계 여성'];
const titles={lobby:'대기방',propose:'제시어 제안',vote:'익명 투표',countdown:'게임 시작 카운트다운',turn:'질문 / 정답 도전',answer:'답변 중',reveal:'답변 공개',judge:'정답 인정 투표',success:'탈출 성공',miss:'오답',results:'최종 결과',waiting:'재접속 대기'};
let token=sessionStorage.getItem('wai-session'),state=null,controller=null,streamGeneration=0,lastKey='',lastSeq=-1,choice='',target='',mode='question',avatar=Number(localStorage.getItem('wai-avatar')??1),seenChats=new Set(),sound=false,offset=0,errorTimer;
const portrait=a=>`<div class="portrait" role="img" aria-label="${types[a]}" style="background-position:${a%4*100/3}% ${Math.floor(a/4)*100/3}%"></div>`;
const player=id=>state.players.find(p=>p.id===id),me=()=>player(state.me),name=id=>player(id)?.name||'퇴장한 유저';
const hero=id=>{let p=player(id)||me();return `<div class="hero ${state.phase==='success'?'winner':''}">${portrait(p.avatar)}<div class="hero-label">${p.number?String(p.number).padStart(2,'0')+' · ':''}${esc(p.name)}</div></div>`};
const dots='<div aria-label="기다리는 중"><i class="waiting-dot"></i><i class="waiting-dot"></i><i class="waiting-dot"></i></div>';
const wait=t=>`<h1>${t}</h1>${dots}<p class="wait">잠시만 기다려 주세요.</p>`;
function error(m){$('#error').textContent=m;clearTimeout(errorTimer);errorTimer=setTimeout(()=>$('#error').textContent='',7000)}
function tone(){if(!sound)return;try{let a=new AudioContext(),o=a.createOscillator(),g=a.createGain();g.gain.value=.035;o.frequency.value=520;o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.1);o.onended=()=>a.close()}catch{}}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined});let d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'서버 연결을 확인하세요.'),{status:r.status});return d}
async function act(type,data={}){try{let s=await api('action',{type,seq:state.seq,...data});update(s);return true}catch(e){error(e.message);return false}}
function saveProfile(){localStorage.setItem('wai-name',$('#nickname')?.value.trim()||me()?.name||'');localStorage.setItem('wai-avatar',avatar)}
function welcome(){state=null;lastKey='';$('#welcome').hidden=false;$('main').hidden=true;$('footer').hidden=true;$('#leave').hidden=true;$('#phase').textContent='사교 클럽에 오신 것을 환영합니다';$('#timer').textContent='';$('#welcome').innerHTML=`<section class="welcome"><div class="welcome-grid"><div><span class="eyebrow">WHO IS BEHIND YOUR NAME?</span><h1>모두가 아는 당신.<br>당신만 모르는 정체.</h1><p class="intro">친구들이 골라준 비밀 인물을 질문으로 추리하세요.<br>3~8명이 함께하는 사교 클럽의 추리 게임.</p>${portrait(avatar)}</div><div><label for="nickname">닉네임</label><input id="nickname" maxlength="16" autocomplete="nickname" value="${esc(localStorage.getItem('wai-name')||'')}"><div class="actions"><button id="create">새 방 만들기</button></div><div class="paper"><label for="roomCode">초대 코드로 입장</label><input id="roomCode" maxlength="6" placeholder="6자리 방 코드" value="${esc(new URL(location.href).searchParams.get('room')||'')}"><div class="actions"><button id="join">입장하기</button></div></div><p class="muted">캐릭터는 입장 후 대기방에서 바꿀 수 있습니다.<br>새로고침·연결 끊김 후 60초 안에는 다시 연결됩니다.</p></div></div></section>`;$('#create').onclick=()=>enter('create');$('#join').onclick=()=>enter('join')}
async function enter(path){const nick=$('#nickname').value.trim();if(!nick)return error('닉네임을 입력하세요.');try{const d=await api(path,{name:nick,avatar,code:$('#roomCode').value.trim()});token=d.token;sessionStorage.setItem('wai-session',token);localStorage.setItem('wai-name',nick);update(d.state);listen()}catch(e){error(e.message)}}
async function listen(){const gen=++streamGeneration;controller?.abort();controller=new AbortController();while(gen===streamGeneration&&token){try{$('#connection').textContent='연결 중…';const r=await fetch('/api/events',{headers:{Authorization:'Bearer '+token},signal:controller.signal});if(!r.ok){const d=await r.json();if(r.status===401||r.status===410){token=null;sessionStorage.removeItem('wai-session');welcome();error(d.error);break}throw new Error(d.error)}$('#connection').textContent='연결됨';const reader=r.body.getReader(),decoder=new TextDecoder();let buf='';while(true){const {value,done}=await reader.read();if(done)break;buf+=decoder.decode(value,{stream:true});let end;while((end=buf.indexOf('\n\n'))>=0){const frame=buf.slice(0,end);buf=buf.slice(end+2);if(frame.startsWith('data: '))update(JSON.parse(frame.slice(6)))}}if(gen!==streamGeneration)break;throw new Error('연결 끊김')}catch(e){if(gen!==streamGeneration||e.name==='AbortError')break;$('#connection').textContent='연결이 끊겼습니다. 재접속 중… (유예 60초)';await new Promise(r=>setTimeout(r,2000))}}}
function update(s){if(state&&s.rev<state.rev)return;state=s;offset=s.serverNow-Date.now();if(me()?.left){token=null;sessionStorage.removeItem('wai-session');streamGeneration++;controller?.abort();welcome();error('방에서 퇴장했습니다.');return}$('#welcome').hidden=true;$('#welcome').replaceChildren();$('main').hidden=false;$('footer').hidden=false;$('#leave').hidden=false;$('#phase').textContent=`${titles[s.phase]} · 방 ${s.code}${s.round?' · '+s.round+'바퀴째':''}`;
const roster=s.players.slice().sort((a,b)=>(a.number??99)-(b.number??99));$('#roster').innerHTML=roster.map(p=>`<div class="player ${p.id===s.me?'self':''} ${p.id===s.turn?'current':''} ${!p.connected?'offline':''} ${p.left?'left':''}">${portrait(p.avatar)}<div>${p.number?String(p.number).padStart(2,'0')+' ':''}${esc(p.name)}<small>${p.left?'중도 퇴장':!p.connected?'재접속 대기':s.phase==='lobby'?(p.ready?'준비 완료':'설정 중'):p.rank?(p.result==='미탈출'?'미탈출 · ':'탈출 ')+p.rank+'위':p.id===s.answerer&&s.phase==='answer'?'답변 중':p.id===s.turn?'현재 차례':'대기 중'}${p.id===s.host?' · 방장':''}</small>${s.phase!=='lobby'?`<span class="secret">${p.secret?esc(p.secret):p.id===s.me?'내 정체: ???':'정체 선정 중'}</span>`:''}</div></div>`).join('');
const own=me();const key=[s.seq,s.phase,s.host,own.ready,own.name,own.avatar,s.ownProposal,s.ownVote,s.phase==='lobby'?s.players.filter(p=>!p.left).map(p=>p.id).join(','):''].join('|');if(key!==lastKey){lastKey=key;const nextSeq=lastSeq!==s.seq;if(nextSeq){lastSeq=s.seq;choice='';target='';mode='question';tone()}render()}
if(s.phase==='lobby'){$('#startGame')?.toggleAttribute('disabled',s.players.filter(p=>!p.left).length<3||s.players.some(p=>!p.left&&(!p.ready||!p.connected)));$('#roomProgress').textContent=`참가자 ${s.players.filter(p=>!p.left).length} / 8`}
if($('#progress'))$('#progress').textContent=s.phase==='propose'?`제출 완료 ${s.submitted.length} / ${s.eligible}`:`투표 완료 ${s.votesCount} / ${s.eligible}`;
// Stable forms and chat inputs survive other players' updates.
if(s.phase==='turn')document.querySelectorAll('[data-target]').forEach(b=>{const p=player(b.dataset.target);b.disabled=!p||!p.connected||p.left;if(b.disabled&&target===p?.id){target='';b.classList.remove('selected')}});
const setup=['propose','vote'].includes(s.phase);$('#message').disabled=setup;$('#message').placeholder=setup?'제시어 선정 중에는 채팅을 잠시 쉬어갑니다.':'메시지를 입력하세요';$('#chat button').disabled=setup;
for(const c of s.chats){if(seenChats.has(c.id))continue;seenChats.add(c.id);if(Date.now()+offset-c.at>5000)continue;const d=document.createElement('div');d.className='bubble';d.textContent=c.name+': '+c.text;d.style.top=5+(seenChats.size%3)*15+'%';$('#stage').append(d);setTimeout(()=>d.remove(),5000)}if(seenChats.size>200)seenChats=new Set(s.chats.map(c=>c.id));clock()}
function render(){const s=state,own=me(),isTurn=s.turn===s.me,isSubject=s.subject===s.me;let focus=s.subject||s.turn||s.me;if(s.phase==='answer'||s.phase==='reveal')focus=s.answerer||s.turn;let body='';
if(s.phase==='lobby'){avatar=own.avatar;body=`<span class="eyebrow">YOUR PRIVATE SOCIAL CLUB</span><h1>당신의 자리를<br>준비해 두었습니다.</h1><div class="caption"><span class="roomcode">${s.code}</span><button id="copyInvite">초대 링크 복사</button></div><p id="roomProgress" class="progress"></p><label for="nickname">닉네임</label><input id="nickname" maxlength="16" value="${esc(own.name)}" ${own.ready?'disabled':''}><div class="actions"><button id="saveProfile" ${own.ready?'disabled':''}>프로필 저장</button><button id="ready">${own.ready?'준비 취소':'준비 완료'}</button></div>${s.host===s.me?'<div class="actions"><button id="startGame">게임 시작</button></div>':'<p class="muted">전원 준비 완료 후 방장이 시작합니다.</p>'}<p class="muted">캐릭터 중복 선택 가능 · 녹색 프레임은 내 자리입니다.</p>`}
if(s.phase==='propose'){body=isSubject?wait('다른 유저들이<br>당신의 정체를 정하고 있어요.'):s.ownProposal?`<h1>제안을 제출했습니다.</h1><div class="paper">${esc(s.ownProposal)}</div>${dots}`:`<h1>${esc(name(s.subject))}의<br>비밀 인물을 제안하세요.</h1><label for="word">인물 이름</label><input id="word" maxlength="40" autocomplete="off"><div class="actions"><button id="propose">제안 제출</button></div><p class="muted">대상 플레이어에게는 후보가 보이지 않습니다.</p>`;body+='<p id="progress" class="progress"></p>'}
if(s.phase==='vote'){body=isSubject?wait('당신의 정체를<br>투표로 고르고 있어요.'):s.ownVote?`<h1>투표를 마쳤습니다.</h1>${dots}<p class="muted">누구에게 투표했는지는 공개되지 않습니다.</p>`:`<h1>${esc(name(s.subject))}의<br>비밀 인물에 투표하세요.</h1><div class="choices">${s.candidates.map((word,i)=>`<button data-vote="${i}">${esc(word)}</button>`).join('')}</div><div class="actions"><button id="vote" disabled>투표 확정</button></div><p class="muted">자신의 제안에도 투표할 수 있습니다.<br>최다 득표 동점은 무작위 선정합니다.</p>`;if(!isSubject)body+='<p id="progress" class="progress"></p>'}
if(s.phase==='countdown')body=`<h1>모든 정체가 정해졌습니다.</h1><div class="paper">첫 바퀴에는 질문만 할 수 있습니다.<br>두 번째 바퀴부터 정답에 도전하세요.</div><p class="wait">곧 게임을 시작합니다.</p>`;
if(s.phase==='turn'){body=isTurn?`<span class="eyebrow">${s.round}바퀴째 · 내 차례</span><h1>어떻게 추리할까요?</h1><div class="actions"><button id="questionMode" class="selected">질문하기</button><button id="guessMode" ${s.round<2?'disabled':''}>정답 도전</button></div><p class="muted">${s.round<2?'정답 도전은 두 번째 바퀴부터 가능합니다.':'질문 또는 정답 중 하나를 제출하세요.'}</p><div id="turnForm"></div>`:wait(`${esc(name(s.turn))} 님의 차례입니다.`)}
if(s.phase==='answer'){body=`<span class="eyebrow">${esc(name(s.turn))}의 질문</span><div class="paper question-card">${esc(s.question)}</div>`+(s.answerer===s.me?'<label for="answer">답변 작성</label><input id="answer" maxlength="200" autocomplete="off"><div class="actions"><button id="answerSend">답변 제출</button></div>':wait(`${esc(name(s.answerer))} 님이<br>답변을 작성하고 있어요.`))}
if(s.phase==='reveal')body=`<span class="eyebrow">${esc(name(s.turn))}의 질문</span><div class="paper question-card">${esc(s.question)}</div><span class="eyebrow">${esc(name(s.answerer))}의 답변</span><div class="paper answer-card">${esc(s.answer)}</div>`;
if(s.phase==='judge'){body=isTurn?`<h1>정답 인정 결과를<br>기다리고 있습니다.</h1><div class="paper">제출한 답: ${esc(s.guess)}</div>${dots}`:`<h1>정답으로 인정할까요?</h1><div class="paper">지정된 정답: <b>${esc(player(s.turn)?.secret)}</b><br>제출한 답: <b>${esc(s.guess)}</b></div>${s.ownVote!==null?'<p class="wait">투표를 제출했습니다.</p>':s.canJudge?'<div class="actions"><button id="accept">인정</button><button class="danger" id="reject">인정하지 않음</button></div>':''}<p class="muted">${s.eligible}명 중 ${s.needed}명 이상 인정하면 정답입니다.</p><p id="progress" class="progress"></p>`}
if(s.phase==='success')body=`<span class="eyebrow">CONGRATULATIONS</span><div class="rank">탈출 ${player(s.turn)?.rank}위</div><h1>${esc(name(s.turn))} 님, 정답입니다!</h1><div class="paper">정체는 <b>${esc(player(s.turn)?.secret)}</b>였습니다.</div><p class="muted">관전하면서 다른 유저의 답변자로 참여합니다.</p>`;
if(s.phase==='miss')body=`<h1>아직 정체를 찾지 못했어요.</h1><div class="paper">${esc(s.message)}</div><p class="muted">다음 플레이어의 차례로 넘어갑니다.</p>`;
if(s.phase==='waiting')body=wait('플레이어의 재접속을 기다립니다.');
if(s.phase==='results'){body=`<div class="results"><span class="eyebrow">THE EVENING'S RESULTS</span><h1>오늘의 탈출 기록</h1><table><thead><tr><th>등수</th><th>플레이어</th><th>정체</th><th>결과</th></tr></thead><tbody>${s.players.slice().sort((a,b)=>(a.rank??99)-(b.rank??99)).map(p=>`<tr><td>${p.rank?p.rank+'위':'—'}</td><td>${p.number??''} ${esc(p.name)}</td><td>${esc(p.secret||'미선정')}</td><td>${esc(p.result||'종료')}</td></tr>`).join('')}</tbody></table>${s.host===s.me?'<div class="actions"><button id="returnLobby">대기방으로</button></div>':'<p class="muted">방장이 대기방으로 돌아가면 다시 준비할 수 있습니다.</p>'}</div>`;$('#stage').innerHTML=body}else $('#stage').innerHTML=hero(focus)+`<div class="panel">${body}</div>`;
$('#bottom').innerHTML=s.phase==='lobby'?`<div class="characters">${types.map((n,i)=>`<button data-avatar="${i}" aria-label="${n} 선택" class="${own.avatar===i?'selected':''}" ${own.ready?'disabled':''}>${portrait(i)}<small>${n}</small></button>`).join('')}</div>`:s.players.filter(p=>p.id!==focus&&!p.left).map(p=>`<div class="card">${portrait(p.avatar)}<span>${p.number} ${esc(p.name)}</span><div class="mini-status">${p.rank?(p.result==='미탈출'?'미탈출 · ':'탈출 ')+p.rank+'위':!p.connected?'재접속 중':''}</div><div class="secret-card">${esc(p.secret||'???')}</div></div>`).join('');
const on=(id,f)=>{if($(id))$(id).onclick=f};
on('#copyInvite',async()=>{try{await navigator.clipboard.writeText(location.origin+'/?room='+s.code);$('#copyInvite').textContent='복사 완료'}catch{error('방 코드 '+s.code+'를 친구에게 전달하세요.')}});
on('#saveProfile',async()=>{if(await act('profile',{name:$('#nickname').value,avatar}))saveProfile()});
on('#ready',async()=>{if(!own.ready){if(!await act('profile',{name:$('#nickname').value,avatar}))return;saveProfile()}await act('ready',{ready:!own.ready})});
on('#startGame',()=>act('start'));on('#propose',()=>act('propose',{text:$('#word').value}));
document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=async()=>{avatar=+b.dataset.avatar;await act('profile',{name:$('#nickname').value,avatar});saveProfile()});
document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{choice=s.candidates[+b.dataset.vote];document.querySelectorAll('[data-vote]').forEach(x=>x.classList.toggle('selected',x===b));$('#vote').disabled=false});on('#vote',()=>act('vote',{text:choice}));
on('#questionMode',()=>{mode='question';turnForm()});on('#guessMode',()=>{mode='guess';turnForm()});if(s.phase==='turn'&&isTurn)turnForm();
on('#answerSend',()=>act('answer',{text:$('#answer').value}));on('#accept',()=>act('judge',{accept:true}));on('#reject',()=>act('judge',{accept:false}));on('#returnLobby',()=>act('return'));
}
function turnForm(){const s=state;$('#questionMode').classList.toggle('selected',mode==='question');$('#guessMode').classList.toggle('selected',mode==='guess');$('#turnForm').innerHTML=mode==='guess'?'<label for="guess">정답 입력</label><input id="guess" maxlength="40" autocomplete="off"><div class="actions"><button id="guessSend">정답 제출</button></div>':`<label for="question">질문 작성</label><input id="question" maxlength="120" placeholder="저는 실존 인물인가요?" autocomplete="off"><p class="muted">답변자를 한 명 선택하세요.</p><div class="choices">${s.players.filter(p=>p.id!==s.me&&!p.left).map(p=>`<button data-target="${p.id}" ${!p.connected?'disabled':''}>${esc(p.name)}${p.rank?' · 관전':''}</button>`).join('')}</div><div class="actions"><button id="questionSend">질문 제출</button></div>`;if(mode==='guess')$('#guessSend').onclick=()=>act('guess',{text:$('#guess').value});else{document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{target=b.dataset.target;document.querySelectorAll('[data-target]').forEach(c=>c.classList.toggle('selected',c===b))});$('#questionSend').onclick=()=>target?act('question',{text:$('#question').value,target}):error('답변자를 선택하세요.')}}
function clock(){if(!state||!state.deadline){$('#timer').textContent='';return}$('#timer').textContent=Math.max(0,Math.ceil((state.deadline-Date.now()-offset)/1000))+'초'}setInterval(clock,250);
$('#chat').onsubmit=async e=>{e.preventDefault();const text=$('#message').value;if(await act('chat',{text}))$('#message').value=''};
$('#history').onclick=()=>{$('#log').innerHTML=state?.logs.length?state.logs.map(l=>`<div class="paper"><b>${esc(name(l.asker))} → ${esc(name(l.responder))}</b><br>Q. ${esc(l.question)}<br>A. ${esc(l.answer)}</div>`).join(''):'아직 질문·답변 기록이 없습니다.';$('#records').showModal()};$('#closeRecords').onclick=()=>$('#records').close();$('#leave').onclick=()=>$('#leaveConfirm').showModal();$('#cancelLeave').onclick=()=>$('#leaveConfirm').close();$('#confirmLeave').onclick=async()=>{await act('leave');streamGeneration++;controller?.abort();token=null;sessionStorage.removeItem('wai-session');$('#leaveConfirm').close();welcome()};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'소리 켜짐':'소리 꺼짐';tone()};
if(token){$('#connection').textContent='참가 정보를 복원하고 있습니다.';listen()}else welcome();
